  `gallery_images` json DEFAULT NULL,
  `venue_types` json DEFAULT NULL,
  `amenities` json DEFAULT NULL,
  `capacity` varchar(100) DEFAULT '',
  `built_year` varchar(50) DEFAULT '',
  `land_size` varchar(100) DEFAULT '',
  `phone` varchar(50) DEFAULT '',
